func (b *BeaconState) CopyAllTries() {
    b.lock.Lock()
    defer b.lock.Unlock()
    for fldIdx, fieldTrie := range b.stateFieldLeaves {
        if fieldTrie.FieldReference() != nil {
            fieldTrie.Lock()
            if fieldTrie.FieldReference().Refs() > 1 {
                fieldTrie.FieldReference().MinusRef()
                newTrie := fieldTrie.CopyTrie()
                b.stateFieldLeaves[fldIdx] = newTrie
            }
            fieldTrie.Unlock()
        }
    }
}

// CopyTrie (FieldTrie) - fieldtrie/field_trie.go lines 171-196
func (f *FieldTrie) CopyTrie() *FieldTrie {
    if f.fieldLayers == nil {
        return &FieldTrie{field: f.field, dataType: f.dataType, reference: stateutil.NewRef(1), ...}
    }
    dstFieldTrie := make([][]*[32]byte, len(f.fieldLayers))
    for i, layer := range f.fieldLayers {
        dstFieldTrie[i] = make([]*[32]byte, len(layer))
        copy(dstFieldTrie[i], layer) // copies [32]byte POINTERS, not values
